package limiter

import (
	"errors"
	"sync"
	"time"
)

var ErrInvalidCapacity = errors.New("limiter: capacity must be > 0")

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	capacity float64
	rate     float64 // tokens per second
	tokens   float64
	last     time.Time
	clock    Clock
}

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second), starting full. rate must be > 0.
func New(capacity int, rate float64) (*Limiter, error) {
	return NewWithClock(capacity, rate, realClock{})
}

// NewWithClock is New with an injectable clock.
func NewWithClock(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 {
		return nil, ErrInvalidCapacity
	}
	if rate <= 0 {
		return nil, errors.New("limiter: rate must be > 0")
	}
	if clock == nil {
		return nil, errors.New("limiter: nil clock")
	}
	return &Limiter{
		capacity: float64(capacity),
		rate:     rate,
		tokens:   float64(capacity),
		clock:    clock,
	}, nil
}

// refill advances the bucket to time now.
func (l *Limiter) refill(now time.Time) {
	if now.After(l.last) {
		l.tokens += now.Sub(l.last).Seconds() * l.rate
		if l.tokens > l.capacity {
			l.tokens = l.capacity
		}
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time.Now.
func (l *Limiter) AllowN(n int) bool {
	return l.AllowNAt(n, l.clock.Now())
}

// AllowNAt reports whether n tokens may be consumed at the given time.
// It is safe for concurrent use.
func (l *Limiter) AllowNAt(n int, now time.Time) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	f := float64(n)
	if l.tokens < f {
		return false
	}
	l.tokens -= f
	return true
}

// RetryAfter returns the duration until n tokens would be available,
// or 0 if they are available now.
func (l *Limiter) RetryAfter(n int) time.Duration {
	return l.RetryAfterAt(n, l.clock.Now())
}

func (l *Limiter) RetryAfterAt(n int, now time.Time) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.refill(now)
	need := float64(n) - l.tokens
	if need <= 0 {
		return 0
	}
	return time.Duration(need / l.rate * float64(time.Second))
}
