package limiter

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

// SystemClock uses the real wall clock.
type SystemClock struct{}

// Now returns the current time.
func (SystemClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
type Limiter struct {
	mu       sync.Mutex
	capacity int
	tokens   float64
	rate     float64 // tokens per second
	last     time.Time
	clock    Clock
}

// ErrInvalidConfig is returned for invalid constructor arguments.
var ErrInvalidConfig = errors.New("limiter: capacity and rate must be positive")

// New creates a Limiter with the given burst capacity and refill rate
// (tokens per second). The bucket starts full.
func New(capacity int, rate float64, clock Clock) (*Limiter, error) {
	if capacity <= 0 || rate <= 0 {
		return nil, ErrInvalidConfig
	}
	if clock == nil {
		clock = SystemClock{}
	}
	return &Limiter{
		capacity: capacity,
		tokens:   float64(capacity),
		rate:     rate,
		last:     clock.Now(),
		clock:    clock,
	}, nil
}

// refill advances the bucket to time now.
func (l *Limiter) refill(now time.Time) {
	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.rate
		if l.tokens > float64(l.capacity) {
			l.tokens = float64(l.capacity)
		}
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time now,
// consuming them if so.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	l.refill(now)
	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// RetryAfter returns the duration until n tokens would be available,
// or 0 if they are available now.
func (l *Limiter) RetryAfter(n int) time.Duration {
	now := l.clock.Now()
	l.mu.Lock()
	defer l.mu.Unlock()

	l.refill(now)
	need := float64(n) - l.tokens
	if need <= 0 {
		return 0
	}
	return time.Duration(need / l.rate * float64(time.Second))
}
